// the whole point of this instance — takes effect immediately on the next
// build, and the same file is the thing you port back into the real
// product's lib/agent.ts SYSTEM constant once a change proves out.

async function loadHouseStyle(): Promise<string> {
  const skillPath = path.join(process.cwd(), "skills/kodely-house-style/SKILL.md");
  const raw = await readFile(skillPath, "utf8");
  return raw.replace(/^---\n[\s\S]*?\n---\n/, "").trim();
}

/** Reject path traversal and absolute paths before anything touches the DB. */
export function normalizePath(raw: string): string | null {
  const p = raw.trim().replace(/^\.?\//, "");
  if (!p || p.length > 200) return null;
  if (p.includes("..") || p.startsWith("/") || p.includes("\\")) return null;
  if (!/^[A-Za-z0-9._/-]+$/.test(p)) return null;
  return p;
}

async function writeFileMap(dir: string, files: FileMap) {
  for (const [rel, content] of Object.entries(files)) {
    const full = path.join(dir, rel);
    await mkdir(path.dirname(full), { recursive: true });
    await writeFile(full, content, "utf8");
  }
}

async function readFileTree(dir: string): Promise<FileMap> {
  const paths = await fg("**/*", { cwd: dir, dot: false, onlyFiles: true, ignore: ["node_modules/**", ".git/**"] });
  const out: FileMap = {};
  for (const rel of paths) {
    out[rel] = await readFile(path.join(dir, rel), "utf8");
  }
  return out;
}

