        for (const block of message.message.content) {
          if ("text" in block && block.text) yield { type: "text", text: block.text };
        }
      } else if (message.type === "result") {
        // Subscription-billed — nothing to meter, so usage is reported as
        // zero rather than guessed. credits.ts computes 0 credits from this
        // regardless of the `model` string, so every personal build is free.
        yield {
          type: "usage",
          model: "claude-agent-sdk-personal",
          inputTokens: 0,
          outputTokens: 0,
          cacheReadTokens: 0,
          cacheWriteTokens: 0,
        };
      }
    }

    if (opts.signal?.aborted) return;

    const after = await readFileTree(workDir);

    for (const [p, content] of Object.entries(after)) {
      const normalized = normalizePath(p);
      if (!normalized) continue;
      if (opts.files[p] === content) continue; // unchanged
      const ok = await opts.onWrite(normalized, content);
      if (ok) yield { type: "file", path: normalized, action: "write" };
    }
    for (const p of Object.keys(opts.files)) {
      if (p in after) continue;
      const normalized = normalizePath(p);
      if (!normalized) continue;
      const ok = await opts.onDelete(normalized);
      if (ok) yield { type: "file", path: normalized, action: "delete" };
    }
  } finally {
    await rm(workDir, { recursive: true, force: true });
  }
}

