"use client";

import { useEffect, useMemo, useState } from "react";
import { CardModal } from "@/components/CardModal";
import { MicButton } from "@/components/MicButton";
import { Board, Card, CardPatch, CardPriority, CardType, Column, parseLabels } from "@/lib/types";

const PHASE_LABEL: Record<string, string> = {
  A: "Phase A · Blockers",
  B: "Phase B · Finish the MVP",
  C: "Phase C · Operate & grow",
  D: "Phase D · Backend & moat",
};

const TYPE_COLOR: Record<CardType, string> = {
  IDEA: "var(--phase-d)",
  FEATURE: "var(--accent)",
  BUG: "var(--phase-a)",
  CHORE: "var(--faint)",
};

const PRIORITY_DOT: Record<CardPriority, string> = {
  LOW: "var(--faint)",
  NORMAL: "var(--ink-2)",
  HIGH: "var(--phase-b)",
  URGENT: "var(--phase-a)",
};

function PhaseBadge({ phase }: { phase: Card["phase"] }) {
  if (!phase) return null;
  return (
    <span
      className="inline-flex items-center rounded-full px-2 py-0.5 font-mono text-[10px] font-medium uppercase tracking-wide"
      style={{
        color: `var(--phase-${phase.toLowerCase()})`,
        background: `color-mix(in srgb, var(--phase-${phase.toLowerCase()}) 12%, transparent)`,
      }}
      title={PHASE_LABEL[phase]}
    >
      {phase}
    </span>
  );
}

export default function BoardPage() {
  const [boards, setBoards] = useState<Board[]>([]);
  const [boardId, setBoardId] = useState<string | null>(null);
  const [columns, setColumns] = useState<Column[]>([]);
  const [cards, setCards] = useState<Card[]>([]);
  const [newCardText, setNewCardText] = useState<Record<string, string>>({});
  const [newColumnName, setNewColumnName] = useState("");
  const [dragging, setDragging] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [showArchived, setShowArchived] = useState(false);
  const [openCardId, setOpenCardId] = useState<string | null>(null);
  const [addingBoard, setAddingBoard] = useState(false);
  const [newBoardName, setNewBoardName] = useState("");

  useEffect(() => {
    fetch("/api/boards")
      .then((r) => r.json())
      .then((d) => {
        setBoards(d.boards ?? []);
        setBoardId((prev) => prev ?? d.boards?.[0]?.id ?? null);
      });
  }, []);

  useEffect(() => {
    if (boardId === null && boards.length === 0) return;
    setLoading(true);
    const url = boardId ? `/api/board?boardId=${boardId}` : "/api/board";
    fetch(url)
      .then((r) => r.json())
      .then((d) => {
        setColumns(d.columns ?? []);
        setCards(d.cards ?? []);
        setLoading(false);
      });
  }, [boardId, boards.length]);

  const openCard = useMemo(() => cards.find((c) => c.id === openCardId) ?? null, [cards, openCardId]);

  async function addCard(columnId: string) {
    const title = (newCardText[columnId] ?? "").trim();
    if (!title) return;
    setNewCardText((s) => ({ ...s, [columnId]: "" }));
    const res = await fetch("/api/board", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ columnId, title }),
    });
    const { card } = await res.json();
    if (card) setCards((c) => [...c, { ...card, attachmentCount: 0, commentCount: 0 }]);
  }

  async function deleteCard(id: string) {
    setCards((c) => c.filter((x) => x.id !== id));
    if (openCardId === id) setOpenCardId(null);
    await fetch(`/api/cards/${id}`, { method: "DELETE" });
  }

  async function moveCard(cardId: string, columnId: string) {
    const position = cards.filter((c) => c.columnId === columnId).length;
    setCards((c) => c.map((x) => (x.id === cardId ? { ...x, columnId, position } : x)));
    await fetch(`/api/cards/${cardId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ columnId, position }),
    });
  }

  async function updateCard(patch: CardPatch) {
    const { id, ...rest } = patch;
    setCards((c) =>
      c.map((x) => {
        if (x.id !== id) return x;
        const next = { ...x };
        if (rest.title !== undefined) next.title = rest.title;
        if (rest.description !== undefined) next.description = rest.description;
        if (rest.type !== undefined) next.type = rest.type;
        if (rest.priority !== undefined) next.priority = rest.priority;
        if (rest.labels !== undefined) next.labels = JSON.stringify(rest.labels);
        if (rest.assignee !== undefined) next.assignee = rest.assignee;
        if (rest.archived !== undefined) next.archivedAt = rest.archived ? new Date().toISOString() : null;
        return next;
      }),
    );
    await fetch(`/api/cards/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(rest),
    });
  }

  async function addColumn() {
    const name = newColumnName.trim();
    if (!name || !boardId) return;
    setNewColumnName("");
    const res = await fetch("/api/columns", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ boardId, name }),
    });
    const { column } = await res.json();
    if (column) setColumns((c) => [...c, column]);
  }

  async function renameColumn(id: string, name: string) {
    setColumns((c) => c.map((x) => (x.id === id ? { ...x, name } : x)));
    await fetch(`/api/columns/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
  }

  async function deleteColumn(id: string) {
    if (!confirm("Delete this column and all its cards?")) return;
    setColumns((c) => c.filter((x) => x.id !== id));
    setCards((c) => c.filter((x) => x.columnId !== id));
    await fetch(`/api/columns/${id}`, { method: "DELETE" });
  }

  async function createBoard() {
    const name = newBoardName.trim();
    if (!name) return;
    setNewBoardName("");
    setAddingBoard(false);
    const res = await fetch("/api/boards", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    const { board } = await res.json();
    if (board) {
      setBoards((b) => [...b, board]);
      setBoardId(board.id);
    }
  }

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center text-sm text-[var(--faint)]">
        Loading board…
      </div>
    );
  }

  return (
    <div className="min-h-screen px-6 py-10 sm:px-10">
      <header className="mb-8 flex flex-wrap items-start justify-between gap-4">
        <div>
          <p className="font-mono text-xs font-medium uppercase tracking-[0.14em] text-[var(--faint)]">
            Personal build board
          </p>
          <h1 className="mt-2 text-3xl font-semibold tracking-tight">
            <span className="brand-gradient-text">kodely</span> board
          </h1>
          <p className="mt-2 max-w-lg text-sm text-[var(--ink-2)]">
            Yours to reshape — running entirely on your own machine.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <select
            value={boardId ?? ""}
            onChange={(e) => setBoardId(e.target.value)}
            className="rounded-lg border bg-transparent px-3 py-1.5 text-sm outline-none"
            style={{ borderColor: "var(--line)" }}
          >
            {boards.map((b) => (
              <option key={b.id} value={b.id}>
                {b.name}
              </option>
            ))}
          </select>
          {addingBoard ? (
            <input
              autoFocus
              value={newBoardName}
              onChange={(e) => setNewBoardName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && createBoard()}
              onBlur={() => (newBoardName.trim() ? createBoard() : setAddingBoard(false))}
              placeholder="Board name…"
              className="w-36 rounded-lg border bg-transparent px-2.5 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
              style={{ borderColor: "var(--line)" }}
            />
          ) : (
            <button
              onClick={() => setAddingBoard(true)}
              className="rounded-lg border px-3 py-1.5 text-sm text-[var(--ink-2)] hover:text-[var(--accent)]"
              style={{ borderColor: "var(--line)" }}
            >
              + Board
            </button>
          )}
          <button
            onClick={() => setShowArchived((s) => !s)}
            className="rounded-lg border px-3 py-1.5 text-sm"
            style={{
              borderColor: "var(--line)",
              color: showArchived ? "var(--accent)" : "var(--ink-2)",
              background: showArchived ? "color-mix(in srgb, var(--accent) 10%, transparent)" : "transparent",
            }}
          >
            {showArchived ? "Showing archived" : "Show archived"}
          </button>
        </div>
      </header>

      <div className="flex gap-5 overflow-x-auto pb-6">
        {columns.map((col) => {
          const colCards = cards
            .filter((c) => c.columnId === col.id && !!c.archivedAt === showArchived)
            .sort((a, b) => a.position - b.position);
          return (
            <div
              key={col.id}
              className="flex w-80 shrink-0 flex-col rounded-2xl border p-3"
              style={{ borderColor: "var(--line)", background: "var(--panel)", boxShadow: "var(--sh-s)" }}
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => {
                e.preventDefault();
                if (dragging) moveCard(dragging, col.id);
                setDragging(null);
              }}
            >
              <div className="flex items-center justify-between gap-2 px-1 pb-3">
                <input
                  value={col.name}
                  onChange={(e) => renameColumn(col.id, e.target.value)}
                  className="w-full truncate bg-transparent text-sm font-semibold outline-none"
                />
                <span className="shrink-0 font-mono text-xs text-[var(--faint)]">{colCards.length}</span>
                <button
                  onClick={() => deleteColumn(col.id)}
                  aria-label={`Delete column ${col.name}`}
                  className="shrink-0 text-[var(--faint)] hover:text-[var(--phase-a)]"
                >
                  ×
                </button>
              </div>

              <div className="flex flex-col gap-2">
                {colCards.map((card) => {
                  const labels = parseLabels(card.labels);
                  return (
                    <div
                      key={card.id}
                      draggable
                      onDragStart={() => setDragging(card.id)}
                      onDragEnd={() => setDragging(null)}
                      onClick={() => setOpenCardId(card.id)}
                      className="group cursor-grab rounded-xl border p-3 active:cursor-grabbing"
                      style={{ borderColor: "var(--line)", background: "var(--background)" }}
                    >
                      <div className="flex items-start justify-between gap-2">
                        <p className="text-sm font-medium leading-snug">{card.title}</p>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            deleteCard(card.id);
                          }}
                          className="shrink-0 text-[var(--faint)] opacity-0 transition-opacity hover:text-[var(--accent)] group-hover:opacity-100"
                          aria-label="Delete card"
                        >
                          ×
                        </button>
                      </div>
                      {card.description && (
                        <p className="mt-1.5 line-clamp-2 text-xs leading-relaxed text-[var(--ink-2)]">
                          {card.description}
                        </p>
                      )}
                      <div className="mt-2 flex flex-wrap items-center gap-1.5">
                        <PhaseBadge phase={card.phase} />
                        <span
                          className="inline-flex items-center rounded-full px-2 py-0.5 font-mono text-[10px] font-medium"
                          style={{
                            color: TYPE_COLOR[card.type],
                            background: `color-mix(in srgb, ${TYPE_COLOR[card.type]} 12%, transparent)`,
                          }}
                        >
                          {card.type}
                        </span>
                        <span
                          className="inline-block h-1.5 w-1.5 rounded-full"
                          style={{ background: PRIORITY_DOT[card.priority] }}
                          title={card.priority}
                        />
                        {labels.map((l) => (
                          <span key={l} className="rounded-full bg-[var(--line-2)] px-2 py-0.5 text-[10px] text-[var(--ink-2)]">
                            {l}
                          </span>
                        ))}
                        {card.assignee && (
                          <span className="text-[10px] text-[var(--faint)]">@{card.assignee}</span>
                        )}
                        {card.attachmentCount > 0 && (
                          <span className="text-[10px] text-[var(--faint)]">📎 {card.attachmentCount}</span>
                        )}
                        {card.commentCount > 0 && (
                          <span className="text-[10px] text-[var(--faint)]">💬 {card.commentCount}</span>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>

              {!showArchived && (
                <div className="mt-2 flex items-center gap-1.5 px-1 pt-1">
                  <input
                    value={newCardText[col.id] ?? ""}
                    onChange={(e) => setNewCardText((s) => ({ ...s, [col.id]: e.target.value }))}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") addCard(col.id);
                    }}
                    placeholder="Add a card…"
                    className="w-full rounded-lg border bg-transparent px-2.5 py-1.5 text-xs outline-none placeholder:text-[var(--faint)]"
                    style={{ borderColor: "var(--line)" }}
                  />
                  <MicButton
                    value={newCardText[col.id] ?? ""}
                    onChange={(v) => setNewCardText((s) => ({ ...s, [col.id]: v }))}
                  />
                </div>
              )}
            </div>
          );
        })}

        <div className="flex w-64 shrink-0 flex-col gap-1.5 rounded-2xl border border-dashed p-3" style={{ borderColor: "var(--line)" }}>
          <input
            value={newColumnName}
            onChange={(e) => setNewColumnName(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && addColumn()}
            placeholder="+ Add column…"
            className="w-full rounded-lg bg-transparent px-2 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
          />
        </div>
      </div>

      {openCard && (
        <CardModal card={openCard} onClose={() => setOpenCardId(null)} onUpdate={updateCard} onDelete={deleteCard} />
      )}
    </div>
  );
}

