file.content:
export type Board = { id: string; name: string; position: number };

export type Column = { id: string; boardId: string; name: string; position: number };

export type CardType = "IDEA" | "FEATURE" | "BUG" | "CHORE";
export type CardPriority = "LOW" | "NORMAL" | "HIGH" | "URGENT";

export type Card = {
  id: string;
  columnId: string;
  title: string;
  description: string;
  phase: "A" | "B" | "C" | "D" | null;
  type: CardType;
  priority: CardPriority;
  labels: string; // JSON-encoded string[]
  assignee: string | null;
  position: number;
  archivedAt: string | null;
  createdAt: string;
  attachmentCount: number;
  commentCount: number;
};

export type Attachment = {
  id: string;
  cardId: string;
  filename: string;
  mime: string;
  sizeBytes: number;
  kind: "IMAGE" | "VIDEO" | "FILE";
  createdAt: string;
};

export type Comment = {
  id: string;
  cardId: string;
  authorName: string;
  body: string;
  createdAt: string;
};

export type CardPatch = {
  id: string;
  columnId?: string;
  position?: number;
  title?: string;
  description?: string;
  type?: CardType;
  priority?: CardPriority;
  labels?: string[];
  assignee?: string | null;
  archived?: boolean;
};

export const CARD_TYPES: CardType[] = ["IDEA", "FEATURE", "BUG", "CHORE"];
export const CARD_PRIORITIES: CardPriority[] = ["LOW", "NORMAL", "HIGH", "URGENT"];

export function parseLabels(labels: string): string[] {
  try {
    const arr = JSON.parse(labels);
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

