  const cards = [...document.querySelectorAll('.group.cursor-grab')];
  const first = cards[0];
  const r1 = first.getBoundingClientRect();
  const colDivs = [...document.querySelectorAll('[class*="thin-scroll"]')];
  const targetCol = colDivs[1];
  const r2 = targetCol.getBoundingClientRect();
  const startX = r1.x + r1.width/2, startY = r1.y + 20;
  const endX = r2.x + r2.width/2, endY = r2.y + 30;

  function fire(el, type, x, y, buttons) {
    const ev = new PointerEvent(type, { bubbles: true, cancelable: true, pointerId: 1, pointerType: 'mouse', clientX: x, clientY: y, button: 0, buttons: buttons, isPrimary: true });
    el.dispatchEvent(ev);
  }
  fire(first, 'pointerdown', startX, startY, 1);
  for (let i = 1; i <= 10; i++) {
    const t = i / 10;
    fire(document, 'pointermove', startX + (endX-startX)*t, startY + (endY-startY)*t, 1);
  }
  fire(document, 'pointerup', endX, endY, 0);
  return document.title;
})();

