1	@import "tailwindcss";
2	
3	/* Class-based dark mode (".dark" on <html>) so the manual theme toggle can
4	   override the OS preference — Tailwind's dark: classes elsewhere in the
5	   app are unaffected in shape, only in what triggers them. */
6	@custom-variant dark (&:where(.dark, .dark *));
7	
8	:root {
9	  --background: #ffffff;
10	  --foreground: #171717;
11	
12	  /* Kodely brand tokens — ported 1:1 from the approved reference mockup
13	     (scratchpad/kodely.html) so the shipped site and the approved design
14	     don't drift again. */
15	  --ink-2: #605b66;
16	  --faint: #a49fad;
17	  --line: rgba(11, 10, 13, 0.09);
18	  --line-2: rgba(11, 10, 13, 0.045);
19	  --panel: #ffffff;
20	  --accent: #e01b6e;
21	  --glow: rgba(247, 37, 112, 0.13);
22	  --glow-2: rgba(163, 61, 255, 0.12);
23	  --sh-s: 0 1px 2px rgba(11, 10, 13, 0.04), 0 6px 16px -8px rgba(11, 10, 13, 0.1);
24	  --sh: 0 40px 100px -50px rgba(120, 40, 160, 0.3), 0 18px 50px -30px rgba(11, 10, 13, 0.16);
25	
26	  --brand-gradient: linear-gradient(100deg, #f72570 0%, #ff6b67 44%, #ff9868 66%, #a33dff 100%);
27	}
28	
29	@theme inline {
30	  --color-background: var(--background);
31	  --color-foreground: var(--foreground);
32	  --font-sans: var(--font-geist-sans);
33	  --font-mono: var(--font-geist-mono);
34	}
35	
36	@media (prefers-color-scheme: dark) {
37	  :root:not(.light) {
38	    --background: #0a0a0a;
39	    --foreground: #ededed;
40	    --ink-2: #a8a1b0;
41	    --faint: #5f5869;
42	    --line: rgba(246, 243, 247, 0.1);
43	    --line-2: rgba(246, 243, 247, 0.05);
44	    --panel: #100e15;
45	    --accent: #ff5c97;
46	    --glow: rgba(255, 76, 139, 0.22);
47	    --glow-2: rgba(180, 114, 255, 0.2);
48	    --sh-s: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 20px -10px rgba(0, 0, 0, 0.6);
49	    --sh: 0 50px 120px -50px rgba(0, 0, 0, 0.8), 0 20px 60px -30px rgba(180, 114, 255, 0.4);
50	    --brand-gradient: linear-gradient(100deg, #ff4c8b 0%, #ff8778 44%, #ffae7e 66%, #b472ff 100%);
51	  }
52	}
53	
54	:root.dark {
55	  --background: #0a0a0a;
56	  --foreground: #ededed;
57	  --ink-2: #a8a1b0;
58	  --faint: #5f5869;
59	  --line: rgba(246, 243, 247, 0.1);
60	  --line-2: rgba(246, 243, 247, 0.05);
61	  --panel: #100e15;
62	  --accent: #ff5c97;
63	  --glow: rgba(255, 76, 139, 0.22);
64	  --glow-2: rgba(180, 114, 255, 0.2);
65	  --sh-s: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 20px -10px rgba(0, 0, 0, 0.6);
66	  --sh: 0 50px 120px -50px rgba(0, 0, 0, 0.8), 0 20px 60px -30px rgba(180, 114, 255, 0.4);
67	  --brand-gradient: linear-gradient(100deg, #ff4c8b 0%, #ff8778 44%, #ffae7e 66%, #b472ff 100%);
68	}
69	
70	body {
71	  background: var(--background);
72	  color: var(--foreground);
73	  font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
74	}
75	
76	.brand-gradient-text {
77	  background: var(--brand-gradient);
78	  -webkit-background-clip: text;
79	  background-clip: text;
80	  color: transparent;
81	}
82	
83	/* Ambient background — one very slow, very soft light behind every
84	   marketing page. Fixed, never scrolls, never shifts color — the motion
85	   budget is spent on foreground elements, not this. */
86	.aura {
87	  position: fixed;
88	  inset: 0;
89	  z-index: 0;
90	  pointer-events: none;
91	  overflow: hidden;
92	}
93	.aura b {
94	  position: absolute;
95	  border-radius: 50%;
96	  filter: blur(120px);
97	  opacity: 0.6;
98	}
99	.aura .a1 {
100	  width: 52vw;
101	  height: 52vw;
102	  left: -8vw;
103	  top: -14vw;
104	  background: radial-gradient(closest-side, var(--glow), transparent);
105	}
106	.aura .a2 {
107	  width: 46vw;
108	  height: 46vw;
109	  right: -10vw;
110	  bottom: -4vw;
111	  background: radial-gradient(closest-side, var(--glow-2), transparent);
112	}
113	
114	@keyframes marquee {
115	  from {
116	    transform: translateX(0);
117	  }
118	  to {
119	    transform: translateX(-50%);
120	  }
121	}
122	
123	/* CTA button hover treatment — ported from Nxeon's real .btn-deploy
124	   pattern (see that codebase's app/globals.css) using Kodely's own brand
125	   gradient instead of Nxeon's blue/purple one. Two pieces:
126	   1. .btn-shine — a one-shot shimmer sweep on hover (all CTAs).
127	   2. .btn-cta-gradient — the background gradient itself shifts position on
128	      hover (only on buttons whose background already IS the brand
129	      gradient — a plain dark/monochrome button has no gradient to shift). */
130	@keyframes btn-shine {
131	  from {
132	    left: -40%;
133	  }
134	  to {
135	    left: 120%;
136	  }
137	}
138	.group:hover .btn-shine {
139	  animation: btn-shine 0.75s ease;
140	}
141	
142	.btn-cta-gradient {
143	  background-image: var(--brand-gradient);
144	  background-size: 220% 100%;
145	  background-position: 0% 0;
146	  transition: background-position 0.6s ease;
147	}
148	.group:hover .btn-cta-gradient {
149	  background-position: 100% 0;
150	}
151	
152	/* Prose styling for blog/SEO content (BlogPost.bodyHtml) — hand-rolled
153	   instead of a Tailwind typography plugin dependency, matching the same
154	   near-monochrome + generous-whitespace system as the rest of the site. */
155	.article-body h2 {
156	  margin-top: 2.75rem;
