1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
5	
6	const KW = "#a33dff";
7	const TAG = "var(--accent)";
8	
9	// Three real files from one project, not a single toy snippet — the point
10	// is "this is a real, structured app" (props, a mapped list, conditional
11	// state), not "this is basic HTML with a sprinkle of JS". Still honestly
12	// frontend-only (React/TS/Tailwind) — no backend/API code implied.
13	const FILES = [
14	  {
15	    name: "Hero.tsx",
16	    lines: [
17	      { indent: 0, text: <><span style={{ color: KW }}>export function</span> <span style={{ color: TAG }}>Hero</span>({"{"} title, subtitle {"}"}: HeroProps) {"{"}</> },
18	      { indent: 1, text: <><span style={{ color: KW }}>return</span> (</> },
19	      { indent: 2, text: <>&lt;<span style={{ color: TAG }}>section</span> className=<span style={{ color: "#3ba55c" }}>&quot;py-24 text-center&quot;</span>&gt;</> },
20	      { indent: 3, text: <>&lt;<span style={{ color: TAG }}>h1</span>&gt;{"{"}title{"}"}&lt;/<span style={{ color: TAG }}>h1</span>&gt;</> },
21	      { indent: 3, text: <>&lt;<span style={{ color: TAG }}>p</span>&gt;{"{"}subtitle{"}"}&lt;/<span style={{ color: TAG }}>p</span>&gt;</> },
22	      { indent: 2, text: <>&lt;/<span style={{ color: TAG }}>section</span>&gt;</> },
23	      { indent: 1, text: ")" },
24	      { indent: 0, text: "}" },
25	    ],
26	  },
27	  {
28	    name: "ProductGrid.tsx",
29	    lines: [
30	      { indent: 0, text: <><span style={{ color: KW }}>export function</span> <span style={{ color: TAG }}>ProductGrid</span>({"{"} items {"}"}: {"{"} items: Product[] {"}"}) {"{"}</> },
31	      { indent: 1, text: <><span style={{ color: KW }}>return</span> (</> },
32	      { indent: 2, text: <>&lt;<span style={{ color: TAG }}>div</span> className=<span style={{ color: "#3ba55c" }}>&quot;grid grid-cols-3 gap-4&quot;</span>&gt;</> },
33	      { indent: 3, text: <>{"{"}items.map((p) =&gt; (</> },
34	      { indent: 4, text: <>&lt;<span style={{ color: TAG }}>ProductCard</span> key={"{"}p.id{"}"} {"{"}...p{"}"} /&gt;</> },
35	      { indent: 3, text: <>)){"}"}</> },
36	      { indent: 2, text: <>&lt;/<span style={{ color: TAG }}>div</span>&gt;</> },
37	      { indent: 1, text: ")" },
38	      { indent: 0, text: "}" },
39	    ],
40	  },
41	  {
42	    name: "Nav.tsx",
43	    lines: [
44	      { indent: 0, text: <><span style={{ color: KW }}>const</span> [open, setOpen] = useState(<span style={{ color: "#e0a030" }}>false</span>)</> },
45	      { indent: 0, text: "" },
46	      { indent: 0, text: <><span style={{ color: KW }}>return</span> (</> },
47	      { indent: 1, text: <>&lt;<span style={{ color: TAG }}>nav</span>&gt;</> },
48	      { indent: 2, text: <>{"{"}open && &lt;<span style={{ color: TAG }}>MobileMenu</span> /&gt;{"}"}</> },
49	      { indent: 2, text: <>&lt;<span style={{ color: TAG }}>MenuButton</span> onClick={"{"}() =&gt; setOpen(!open){"}"} /&gt;</> },
50	      { indent: 1, text: <>&lt;/<span style={{ color: TAG }}>nav</span>&gt;</> },
51	      { indent: 0, text: ")" },
