56	/** Code panel cycles through three real files from one project (not one
57	 * toy snippet) with a tab bar, each typing in on its own turn — reads as
58	 * "this is a structured app," the visual argument for "not just basic
59	 * HTML," while staying honest about being frontend-only. */
60	export function CodeVisual() {
61	  const reduced = useReducedMotion();
62	  const [active, setActive] = useState(0);
63	
64	  useEffect(() => {
65	    if (reduced) return;
66	    const id = setInterval(() => setActive((a) => (a + 1) % FILES.length), 5200);
67	    return () => clearInterval(id);
68	  }, [reduced]);
69	
70	  const file = FILES[active];
71	
72	  return (
73	    <div className="w-full overflow-hidden rounded-2xl border border-neutral-200 bg-white shadow-[var(--sh-s)] dark:border-neutral-800 dark:bg-neutral-950">
74	      <div className="flex gap-1 border-b border-neutral-200 px-3 pt-2.5 dark:border-neutral-800">
75	        {FILES.map((f, i) => (
76	          <button
77	            key={f.name}
78	            type="button"
79	            onClick={() => setActive(i)}
80	            className={`rounded-t-md px-3 py-1.5 font-mono text-[11px] transition-colors ${
81	              i === active
82	                ? "bg-neutral-100 text-neutral-900 dark:bg-neutral-900 dark:text-white"
83	                : "text-neutral-400 hover:text-neutral-600 dark:text-neutral-600 dark:hover:text-neutral-400"
84	            }`}
85	          >
86	            {f.name}
87	          </button>
88	        ))}
89	      </div>
90	      <div className="p-6 font-mono text-[13px] leading-[1.85] text-neutral-600 dark:text-neutral-400">
91	        <AnimatePresence mode="wait">
92	          <motion.div
93	            key={file.name}
94	            initial={reduced ? { opacity: 1 } : { opacity: 0 }}
95	            animate={{ opacity: 1 }}
96	            exit={{ opacity: 0 }}
97	            transition={{ duration: 0.25 }}
98	          >
99	            {file.lines.map((line, i) => (
100	              <motion.div
101	                key={i}
102	                initial={reduced ? { opacity: 1 } : { opacity: 0 }}
103	                animate={{ opacity: 1 }}
104	                transition={{ delay: reduced ? 0 : i * 0.14, duration: 0.25 }}
105	                style={{ paddingLeft: `${line.indent * 1.1}rem`, minHeight: "1em" }}
106	              >
107	                {line.text}
108	                {i === file.lines.length - 1 && (
109	                  <motion.span
110	                    className="ml-0.5 inline-block h-[1em] w-[2px] translate-y-[2px] bg-current align-middle"
111	                    animate={{ opacity: [1, 1, 0, 0] }}
112	                    transition={{ duration: 1, repeat: Infinity, times: [0, 0.5, 0.5, 1] }}
113	                  />
114	                )}
115	              </motion.div>
