@import "tailwindcss";

/* Class-based dark mode (".dark" on <html>) so the manual theme toggle can
   override the OS preference — Tailwind's dark: classes elsewhere in the
   app are unaffected in shape, only in what triggers them. */
@custom-variant dark (&:where(.dark, .dark *));

:root {
  --background: #ffffff;
  --foreground: #171717;

  /* Kodely brand tokens — ported 1:1 from the approved reference mockup
     (scratchpad/kodely.html) so the shipped site and the approved design
     don't drift again. */
  --ink-2: #605b66;
  --faint: #a49fad;
  --line: rgba(11, 10, 13, 0.09);
  --line-2: rgba(11, 10, 13, 0.045);
  --panel: #ffffff;
  --accent: #e01b6e;
  --glow: rgba(247, 37, 112, 0.13);
  --glow-2: rgba(163, 61, 255, 0.12);
  --sh-s: 0 1px 2px rgba(11, 10, 13, 0.04), 0 6px 16px -8px rgba(11, 10, 13, 0.1);
  --sh: 0 40px 100px -50px rgba(120, 40, 160, 0.3), 0 18px 50px -30px rgba(11, 10, 13, 0.16);

  --brand-gradient: linear-gradient(100deg, #f72570 0%, #ff6b67 44%, #ff9868 66%, #a33dff 100%);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root:not(.light) {
    --background: #0a0a0a;
    --foreground: #ededed;
    --ink-2: #a8a1b0;
    --faint: #5f5869;
    --line: rgba(246, 243, 247, 0.1);
    --line-2: rgba(246, 243, 247, 0.05);
    --panel: #100e15;
    --accent: #ff5c97;
    --glow: rgba(255, 76, 139, 0.22);
    --glow-2: rgba(180, 114, 255, 0.2);
    --sh-s: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 20px -10px rgba(0, 0, 0, 0.6);
    --sh: 0 50px 120px -50px rgba(0, 0, 0, 0.8), 0 20px 60px -30px rgba(180, 114, 255, 0.4);
    --brand-gradient: linear-gradient(100deg, #ff4c8b 0%, #ff8778 44%, #ffae7e 66%, #b472ff 100%);
  }
}

:root.dark {
  --background: #0a0a0a;
  --foreground: #ededed;
  --ink-2: #a8a1b0;
  --faint: #5f5869;
  --line: rgba(246, 243, 247, 0.1);
  --line-2: rgba(246, 243, 247, 0.05);
  --panel: #100e15;
  --accent: #ff5c97;
  --glow: rgba(255, 76, 139, 0.22);
  --glow-2: rgba(180, 114, 255, 0.2);
  --sh-s: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 20px -10px rgba(0, 0, 0, 0.6);
  --sh: 0 50px 120px -50px rgba(0, 0, 0, 0.8), 0 20px 60px -30px rgba(180, 114, 255, 0.4);
  --brand-gradient: linear-gradient(100deg, #ff4c8b 0%, #ff8778 44%, #ffae7e 66%, #b472ff 100%);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
}

.brand-gradient-text {
  background: var(--brand-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Ambient background — one very slow, very soft light behind every
   marketing page. Fixed, never scrolls, never shifts color — the motion
   budget is spent on foreground elements, not this. */
.aura {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.aura b {
  position: absolute;
  border-radius: 50%;
  filter: blur(120px);
  opacity: 0.6;
}
.aura .a1 {
  width: 52vw;
  height: 52vw;
  left: -8vw;
  top: -14vw;
  background: radial-gradient(closest-side, var(--glow), transparent);
}
.aura .a2 {
  width: 46vw;
  height: 46vw;
  right: -10vw;
  bottom: -4vw;
  background: radial-gradient(closest-side, var(--glow-2), transparent);
}

/* The prompt-box glow ring (PromptHero) — explicit keyframes rather than
   relying on Tailwind's arbitrary `[animation:spin_...]` value syntax to
   pull in its built-in spin keyframes, which isn't guaranteed to be emitted
   when only referenced that way under JIT scanning. */
@keyframes glow-ring-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes glow-ring-spin-reverse {
  to {
    transform: rotate(-360deg);
  }
}
.glow-ring-a {
  animation: glow-ring-spin 6s linear infinite;
}
.glow-ring-b {
  animation: glow-ring-spin-reverse 9s linear infinite;
}

@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* CTA button hover treatment — ported from Nxeon's real .btn-deploy
   pattern (see that codebase's app/globals.css) using Kodely's own brand
   gradient instead of Nxeon's blue/purple one. Two pieces:
   1. .btn-shine — a one-shot shimmer sweep on hover (all CTAs).
   2. .btn-cta-gradient — the background gradient itself shifts position on
      hover (only on buttons whose background already IS the brand
      gradient — a plain dark/monochrome button has no gradient to shift). */
@keyframes btn-shine {
  from {
    left: -40%;
  }
  to {
    left: 120%;
  }
}
.group:hover .btn-shine {
  animation: btn-shine 0.75s ease;
}

.btn-cta-gradient {
  background-image: var(--brand-gradient);
  background-size: 220% 100%;
  background-position: 0% 0;
  transition: background-position 0.6s ease;
}
.group:hover .btn-cta-gradient {
  background-position: 100% 0;
}

/* Prose styling for blog/SEO content (BlogPost.bodyHtml) — hand-rolled
   instead of a Tailwind typography plugin dependency, matching the same
   near-monochrome + generous-whitespace system as the rest of the site. */
.article-body h2 {
  margin-top: 2.75rem;
  margin-bottom: 1rem;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.article-body h3 {
  margin-top: 2rem;
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
  font-weight: 600;
}
.article-body p {
  margin-bottom: 1.25rem;
  line-height: 1.75;
  color: var(--foreground);
}
.article-body ul,
.article-body ol {
  margin: 1.25rem 0 1.25rem 1.25rem;
  line-height: 1.75;
}
.article-body ul {
  list-style: disc;
}
.article-body ol {
  list-style: decimal;
}
.article-body li {
  margin-bottom: 0.4rem;
}
.article-body a {
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--foreground) 30%, transparent);
}
.article-body strong {
  font-weight: 600;
}
.article-body code {
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.875em;
  background: color-mix(in srgb, var(--foreground) 6%, transparent);
  padding: 0.15em 0.4em;
  border-radius: 0.3em;
}
.article-body table {
  width: 100%;
  margin: 1.5rem 0;
  border-collapse: collapse;
  font-size: 0.9rem;
}
.article-body th,
.article-body td {
  border: 1px solid color-mix(in srgb, var(--foreground) 12%, transparent);
  padding: 0.6rem 0.9rem;
  text-align: left;
}
.article-body th {
  font-weight: 600;
  background: color-mix(in srgb, var(--foreground) 4%, transparent);
}
.article-body blockquote {
  border-left: 3px solid color-mix(in srgb, var(--foreground) 20%, transparent);
  padding-left: 1.1rem;
  margin: 1.5rem 0;
  color: color-mix(in srgb, var(--foreground) 70%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.2s !important;
  }
}

