1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { motion, AnimatePresence, useReducedMotion, type Variants } from "framer-motion";
5	import { Check } from "lucide-react";
6	import { Mark } from "./Logo";
7	
8	const PROMPT_TEXT = "A boutique pilates studio with online class booking";
9	
10	const PHASE_DURATIONS = { typing: 2600, building: 2400, live: 5400 } as const;
11	type Phase = "typing" | "building" | "live";
12	const NEXT_PHASE: Record<Phase, Phase> = { typing: "building", building: "live", live: "typing" };
13	
14	// A real booking flow plays out during the "live" phase, not just a static
15	// page — the demo is meant to look like a working app, not a brochure.
16	type BookingStep = "browse" | "clicking" | "confirmed";
17	const BOOKING_DURATIONS: Record<BookingStep, number> = { browse: 1700, clicking: 600, confirmed: 2800 };
18	const NEXT_BOOKING: Record<BookingStep, BookingStep> = { browse: "clicking", clicking: "confirmed", confirmed: "browse" };
19	const BOOKING_TARGET_INDEX = 0;
20	
21	// One fixed frame height, used for every phase — previously the frame
22	// animated its own height per phase, which shifted every section below it
23	// on the page (a visible jitter). Shorter phases just center within the
24	// same fixed space now, so the page around it never moves. Sized to the
25	// live phase's actual content (measured ~363px) plus a little breathing
26	// room — the old 620px value was sized for the earlier Studio Nine demo's
27	// taller content and left a large dead-space gap under this one.
28	const FRAME_HEIGHT = 410;
29	
30	const container: Variants = {
31	  hidden: {},
32	  shown: { transition: { staggerChildren: 0.11, delayChildren: 0.1 } },
33	};
34	const item: Variants = {
35	  hidden: { opacity: 0, y: 12 },
36	  shown: { opacity: 1, y: 0, transition: { duration: 0.5, ease: [0.2, 0.9, 0.2, 1] } },
37	};
38	const blockVariants: Variants = {
39	  hidden: { opacity: 0, scale: 0.85 },
40	  shown: { opacity: 1, scale: 1, transition: { duration: 0.4, ease: [0.2, 0.9, 0.2, 1] } },
41	};
42	
43	function useTypewriter(text: string, active: boolean, msPerChar: number) {
44	  const [count, setCount] = useState(0);
45	  useEffect(() => {
46	    if (!active) {
47	      setCount(0);
48	      return;
49	    }
50	    const id = setInterval(() => {
51	      setCount((c) => (c >= text.length ? c : c + 1));
52	    }, msPerChar);
53	    return () => clearInterval(id);
54	  }, [active, text, msPerChar]);
55	  return text.slice(0, count);
56	}
57	
58	function useEllipsis(active: boolean) {
59	  const [n, setN] = useState(0);
60	  useEffect(() => {
61	    if (!active) return;
62	    const id = setInterval(() => setN((v) => (v + 1) % 4), 400);
63	    return () => clearInterval(id);
64	  }, [active]);
65	  return ".".repeat(n);
66	}
67	
68	const BLOCK_STYLE = {
69	  background: "color-mix(in srgb, var(--accent) 12%, transparent)",
70	  border: "1px solid color-mix(in srgb, var(--accent) 28%, transparent)",
71	};
72	
73	// A real reformer-pilates studio photo, self-hosted under /public (not
74	// hotlinked) — this is Kodely's own marketing chrome (not a customer-
75	// generated site), so it isn't bound by the no-external-requests CSP that
76	// applies to actual generated output.
77	const HERO_IMAGE = "/marketing/bloom-pilates-hero.jpg";
78	
79	const CLASSES = [
80	  { time: "9:00 AM", name: "Reformer Flow", initial: "M", color: "#a15bd0", meta: "3 spots left" },
81	  { time: "11:30 AM", name: "Mat Pilates", initial: "J", color: "#e0729a", meta: "6 spots left" },
82	  { time: "1:00 PM", name: "Power Pilates", initial: "S", color: "#3d9970", meta: "2 spots left" },
83	];
84	
85	/** The one real hero object — a miniature browser frame that plays out the
86	 * actual product loop (type a prompt → watch it build → it's live at a real
87	 * URL) instead of showing a single static screenshot. Loops continuously;
88	 * respects prefers-reduced-motion by settling on the finished "live" frame. */
89	export function HeroMock() {
90	  const reduced = useReducedMotion();
91	  const [phase, setPhase] = useState<Phase>(reduced ? "live" : "typing");
92	  const [liveCycle, setLiveCycle] = useState(0);
93	  const [bookingStep, setBookingStep] = useState<BookingStep>("browse");
94	  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
95	  const bookingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
96	
97	  useEffect(() => {
98	    if (reduced) return;
99	    timeoutRef.current = setTimeout(() => {
100	      setPhase((p) => {
101	        const next = NEXT_PHASE[p];
102	        if (next === "live") setLiveCycle((c) => c + 1);
103	        return next;
104	      });
105	    }, PHASE_DURATIONS[phase]);
106	    return () => {
107	      if (timeoutRef.current) clearTimeout(timeoutRef.current);
108	    };
109	  }, [phase, reduced]);
110	
111	  // Resets to "browse" every time the live phase is (re-)entered, then
112	  // steps itself through click -> confirm while that phase is showing.
113	  useEffect(() => {
114	    setBookingStep("browse");
115	  }, [liveCycle]);
116	
117	  useEffect(() => {
118	    if (phase !== "live" || reduced) return;
119	    bookingTimeoutRef.current = setTimeout(() => {
120	      setBookingStep((s) => NEXT_BOOKING[s]);
121	    }, BOOKING_DURATIONS[bookingStep]);
122	    return () => {
123	      if (bookingTimeoutRef.current) clearTimeout(bookingTimeoutRef.current);
124	    };
125	  }, [bookingStep, phase, reduced]);
126	
127	  const typed = useTypewriter(PROMPT_TEXT, phase === "typing", 34);
128	  const dots = useEllipsis(phase === "building");
129	
130	  return (
131	    <div className="mx-auto w-full max-w-2xl" style={{ perspective: "1800px" }}>
132	      <div className="group overflow-hidden rounded-2xl border border-black/10 bg-white shadow-[0_40px_80px_-32px_rgba(0,0,0,0.25)] transition-transform duration-500 [transform:rotateX(4deg)] hover:[transform:rotateX(0deg)] dark:border-white/10 dark:bg-neutral-900">
133	        <div className="flex items-center gap-2 border-b border-black/10 bg-black/[0.03] px-4 py-2.5 dark:border-white/10 dark:bg-white/[0.03]">
134	          <span className="h-2.5 w-2.5 rounded-full bg-black/15 dark:bg-white/15" />
135	          <span className="h-2.5 w-2.5 rounded-full bg-black/15 dark:bg-white/15" />
136	          <span className="h-2.5 w-2.5 rounded-full bg-black/15 dark:bg-white/15" />
137	          <div className="ml-3 flex-1 overflow-hidden rounded-md bg-black/[0.04] px-3 py-1 text-center font-mono text-[11px] text-black/40 dark:bg-white/[0.06] dark:text-white/40">
138	            <AnimatePresence mode="wait">
139	              {phase === "live" ? (
140	                <motion.span key="url" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
141	                  bloom-pilates.kodely.site
142	                </motion.span>
143	              ) : (
144	                <motion.span key="new" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
145	                  new-project.kodely.site
146	                </motion.span>
147	              )}
148	            </AnimatePresence>
149	          </div>
150	          <div className="hidden items-center gap-1.5 font-mono text-[10px] text-black/30 sm:flex dark:text-white/30">
151	            {phase === "live" ? (
152	              <>
153	                <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]" />
154	                Generated by Kodely
155	              </>
156	            ) : (
157	              <>
158	                <span className="h-1.5 w-1.5 rounded-full bg-neutral-300 dark:bg-neutral-700" />
159	                {phase === "typing" ? "Waiting for prompt" : "Building"}
160	              </>
161	            )}
162	          </div>
163	        </div>
164	
165	        <div
166	          className="relative overflow-hidden bg-[#fbf7f2] dark:bg-[#1c1512]"
167	          style={{ height: FRAME_HEIGHT }}
168	        >
169	          <AnimatePresence mode="wait">
170	            {phase === "typing" && (
171	              <motion.div
172	                key="typing"
173	                initial={{ opacity: 0 }}
174	                animate={{ opacity: 1 }}
175	                exit={{ opacity: 0 }}
176	                className="flex h-full flex-col items-center justify-center gap-5 px-10 text-center"
177	              >
178	                <Mark size={30} />
179	                <div className="w-full max-w-sm rounded-xl border border-[#e4d9cc] bg-white px-4 py-3.5 text-left text-[13px] leading-relaxed text-[#2a1f1a] shadow-sm dark:border-white/10 dark:bg-[#241a15] dark:text-[#f2e9e2]">
180	                  {typed}
181	                  <motion.span
182	                    className="ml-0.5 inline-block h-[1em] w-[2px] translate-y-[2px] bg-current align-middle"
183	                    animate={{ opacity: [1, 1, 0, 0] }}
184	                    transition={{ duration: 0.9, repeat: Infinity, times: [0, 0.5, 0.5, 1] }}
185	                  />
186	                </div>
187	                <p className="text-xs text-[#8a7362] dark:text-[#b39d8a]">Describe it, and Kodely builds it.</p>
188	              </motion.div>
189	            )}
190	
191	            {phase === "building" && (
192	              <motion.div
193	                key="building"
194	                initial="hidden"
195	                animate="shown"
196	                exit={{ opacity: 0 }}
197	                variants={container}
198	                className="flex h-full flex-col items-center justify-center gap-6 px-10"
199	              >
200	                <motion.div variants={item} className="relative flex h-16 w-16 items-center justify-center">
201	                  <motion.span
202	                    aria-hidden
203	                    className="absolute inset-0 rounded-full"
204	                    style={{ background: "conic-gradient(from 0deg, transparent, var(--glow) 20%, transparent 45%)" }}
205	                    animate={{ rotate: 360 }}
206	                    transition={{ duration: 2.2, repeat: Infinity, ease: "linear" }}
207	                  />
208	                  <div className="relative flex h-11 w-11 items-center justify-center rounded-full bg-[#fbf7f2] dark:bg-[#1c1512]">
209	                    <Mark size={26} />
210	                  </div>
211	                </motion.div>
212	
213	                <motion.div variants={item} className="grid w-full max-w-[220px] grid-cols-3 gap-2">
214	                  <motion.div variants={blockVariants} className="col-span-3 h-6 rounded-md" style={BLOCK_STYLE} />
215	                  <motion.div variants={blockVariants} className="col-span-3 h-16 rounded-md" style={BLOCK_STYLE} />
216	                  <motion.div variants={blockVariants} className="h-10 rounded-md" style={BLOCK_STYLE} />
217	                  <motion.div variants={blockVariants} className="h-10 rounded-md" style={BLOCK_STYLE} />
218	                  <motion.div variants={blockVariants} className="h-10 rounded-md" style={BLOCK_STYLE} />
219	                </motion.div>
220	
221	                <motion.p variants={item} className="font-mono text-xs text-[#8a7362] dark:text-[#b39d8a]">
222	                  Building your site{dots}
223	                </motion.p>
224	              </motion.div>
225	            )}
226	
227	            {phase === "live" && (
228	              <motion.div
229	                key={`live-${liveCycle}`}
230	                initial="hidden"
231	                animate="shown"
232	                variants={container}
233	                className="relative flex h-full flex-col px-6 py-6 text-[#201c2b] dark:text-[#f1eef7]"
234	              >
235	                <motion.div variants={item} className="flex items-center justify-between">
236	                  <span className="text-sm font-semibold tracking-tight">Bloom Pilates</span>
237	                  <div className="flex gap-4 text-xs text-[#716b82] dark:text-[#b3aec2]">
238	                    <span>Classes</span>
239	                    <span>Instructors</span>
240	                    <span>Membership</span>
241	                  </div>
242	                </motion.div>
243	
244	                <motion.div
245	                  variants={item}
246	                  className="relative mt-4 flex h-32 flex-col justify-end overflow-hidden rounded-xl p-4"
247	                >
248	                  {/* eslint-disable-next-line @next/next/no-img-element */}
249	                  <img src={HERO_IMAGE} alt="" className="absolute inset-0 h-full w-full object-cover" />
250	                  <div
251	                    aria-hidden
252	                    className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/10 to-transparent"
253	                  />
254	                  <span className="relative text-[10px] font-medium uppercase tracking-[0.14em] text-white/80">
255	                    Book a class
256	                  </span>
257	                  <h3 className="relative mt-1 text-lg font-semibold leading-tight text-white sm:text-xl">
258	                    Strength. Balance. You.
259	                  </h3>
260	                </motion.div>
261	
262	                <motion.div variants={item} className="mt-4 space-y-2">
263	                  {CLASSES.map((c, i) => {
264	                    const isTarget = i === BOOKING_TARGET_INDEX;
265	                    const booked = isTarget && bookingStep === "confirmed";
266	                    const selecting = isTarget && bookingStep === "clicking";
267	                    return (
268	                      <motion.div
269	                        key={c.name}
270	                        animate={{ scale: selecting ? 1.015 : 1 }}
271	                        transition={{ duration: 0.2 }}
272	                        className="flex items-center gap-3 rounded-xl border px-3 py-2.5"
273	                        style={{
274	                          borderColor: booked
275	                            ? "rgba(16,185,129,0.4)"
276	                            : "color-mix(in srgb, currentColor 10%, transparent)",
277	                          background: booked
278	                            ? "rgba(16,185,129,0.06)"
279	                            : "color-mix(in srgb, currentColor 3%, transparent)",
280	                        }}
281	                      >
282	                        <div
283	                          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-xs font-semibold text-white"
284	                          style={{ background: c.color }}
285	                        >
286	                          {c.initial}
287	                        </div>
