input.text:
(function(){
  function check(clipSel, spinSel){
    const clip = document.querySelector(clipSel);
    const spin = document.querySelector(spinSel);
    // offsetWidth/Height are layout sizes, unaffected by any transform.
    const cw = clip.offsetWidth, ch = clip.offsetHeight;
    const sw = spin.offsetWidth, sh = spin.offsetHeight;
    const diag = Math.sqrt(cw*cw + ch*ch);
    // centers must coincide for rotation to stay centered on the clip
    const spinCenterX = spin.offsetLeft + sw/2, spinCenterY = spin.offsetTop + sh/2;
    return {
      clip: {w: cw, h: ch}, spin: {w: sw, h: sh},
      isSquare: sw === sh,
      clipDiagonal: Math.round(diag),
      coversAtEveryAngle: Math.min(sw, sh) >= diag,
      centeredOnClip: Math.abs(spinCenterX - cw/2) < 1 && Math.abs(spinCenterY - ch/2) < 1,
    };
  }
  return JSON.stringify({A: check('.glow-clip-a', '.glow-spin-a'), B: check('.glow-clip-b', '.glow-spin-b')}, null, 1);
})();

