(function(){
  const clip = document.querySelector('.glow-clip-a');
  const composer = document.querySelector('textarea[placeholder*="Describe the site"]').closest('.relative.z-10');
  // Walk ancestors looking for opaque backgrounds and stacking contexts.
  const chain = [];
  let el = clip.parentElement;
  while (el && el !== document.documentElement) {
    const cs = getComputedStyle(el);
    const opaqueBg = cs.backgroundColor && cs.backgroundColor !== 'rgba(0, 0, 0, 0)' && cs.backgroundColor !== 'transparent';
    if (opaqueBg || cs.zIndex !== 'auto' || cs.opacity !== '1' || cs.filter !== 'none' || cs.transform !== 'none') {
      chain.push({tag: el.tagName, cls: el.className.slice(0,40), bg: cs.backgroundColor, z: cs.zIndex, opacity: cs.opacity, transform: cs.transform !== 'none'});
    }
    el = el.parentElement;
  }
  return JSON.stringify({
    glowZIndex: getComputedStyle(clip).zIndex,
    composerZIndex: getComputedStyle(composer).zIndex,
    ancestorsOfInterest: chain,
  }, null, 1);
})();

