(function(){
  function info(sel){
    const el = document.querySelector(sel);
    return el.getAnimations().map(a => ({
      name: a.animationName,
      dur: a.effect.getTiming().duration,
      delay: a.effect.getTiming().delay,
      iters: a.effect.getTiming().iterations,
    }));
  }
  return JSON.stringify({
    clipA: info('.glow-clip-a'),
    clipB: info('.glow-clip-b'),
    spinA: info('.glow-spin-a'),
    zIndexGlow: getComputedStyle(document.querySelector('.glow-clip-a')).zIndex,
  }, null, 1);
})();

