/* Liquid-glass droplets that bead up on the prompt box's bottom edge and
   fall while the user types (PromptHero). The glass read comes from
   backdrop-filter (it refracts whatever is behind it) plus a bright inner
   top highlight and a soft brand-tinted shadow — not from a flat fill.
   The blob is squashed at the edge, necks/stretches as it detaches, then
   thins out as it falls, which is what sells it as liquid rather than a
   moving dot. */
.glass-drip {
  position: absolute;
  top: 100%;
  margin-top: -7px;
  width: 11px;
  height: 13px;
  pointer-events: none;
  border-radius: 52% 48% 45% 55% / 62% 60% 40% 38%;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, white 62%, transparent),
    color-mix(in srgb, var(--accent) 26%, transparent)
  );
  backdrop-filter: blur(3px) saturate(160%);
  -webkit-backdrop-filter: blur(3px) saturate(160%);
  border: 1px solid color-mix(in srgb, white 55%, transparent);
  box-shadow:
    inset 0 1.5px 1px color-mix(in srgb, white 85%, transparent),
    inset 0 -2px 3px color-mix(in srgb, var(--accent) 22%, transparent),
    0 4px 10px -4px var(--glow);
  animation: glass-drip-fall 1.25s cubic-bezier(0.55, 0, 0.75, 0.4) forwards;
}

@keyframes glass-drip-fall {
  0% {
    opacity: 0;
    transform: translate(0, -5px) scale(0.45, 0.35);
  }
  18% {
    opacity: 1;
    /* beaded up, still clinging to the edge and slightly flattened */
    transform: translate(0, 0) scale(1, 0.82);
  }
  34% {
    /* necks — narrow and tall — as it lets go */
    transform: translate(calc(var(--drip-drift) * 0.2), 7px) scale(0.78, 1.32);
  }
  70% {
    opacity: 0.85;
    transform: translate(calc(var(--drip-drift) * 0.7), 26px) scale(0.9, 1.12);
  }
  100% {
    opacity: 0;
    transform: translate(var(--drip-drift), 52px) scale(0.62, 1.45);
  }
}

