}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
}

.brand-gradient-text {
  background: var(--brand-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Ambient background — one very slow, very soft light behind every
   marketing page. Fixed, never scrolls, never shifts color — the motion
   budget is spent on foreground elements, not this. */
.aura {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.aura b {
  position: absolute;
  border-radius: 50%;
  filter: blur(120px);
  opacity: 0.6;
}
.aura .a1 {
  width: 52vw;
  height: 52vw;
  left: -8vw;
  top: -14vw;
  background: radial-gradient(closest-side, var(--glow), transparent);
}
.aura .a2 {
  width: 46vw;
  height: 46vw;
  right: -10vw;
  bottom: -4vw;
  background: radial-gradient(closest-side, var(--glow-2), transparent);
}

/* The prompt-box glow ring (PromptHero) — a Gemini-style "chasing light"
   ring, rebuilt using only decade-old, maximally-compatible CSS: plain
   `transform: rotate()` and `overflow: hidden` clipping. No @property, no
   CSS masking — both were dropped after repeated reports that the effect
   still wasn't appearing correctly even in a fresh browser with a verified
   non-cached, up-to-date stylesheet, which means the earlier @property +
   mask-composite combination (both comparatively modern CSS features) was
   the most likely remaining suspect, even though I could not get direct
   visual confirmation either way in this environment.

   The technique: each layer is a STATIC outer clipper
   (`.glow-clip-a/-b`, position:absolute, overflow:hidden, never
   transforms) containing one OVERSIZED inner rotator
   (`.glow-spin-a/-b`, ~2x the clipper's size, centered via inset:-50%).
   Only the inner rotator spins via plain `transform: rotate()` — since
   it's oversized, its corners sweeping outside a same-sized box (the
   original "wide rectangle rotated as a rigid body" bug) never matters:
   they're clipped away by the static outer box at every angle. The
   composer sitting on top (z-10, opaque) covers the rotator's entire
   interior, leaving only the outer few px visible as a ring — no masking
   needed for that either. */
@keyframes glow-spin {
  to {
    transform: rotate(360deg);
  }
}
.glow-spin-a {
  animation: glow-spin 9s linear infinite;
}
.glow-spin-b {
  animation: glow-spin 14s linear infinite reverse;
}

/* Entrance fade-in — plain CSS on the static outer clipper, not a
   framer-motion `whileInView` (depends on IntersectionObserver + React
   state + framer's scheduling — more moving parts than necessary here).
   `forwards` is load-bearing: without it, the element snaps back to its
   non-animated base style the instant the single iteration ends. */
@keyframes glow-fade-in-a {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
  to {
    opacity: 0.5;
    transform: scale(1);
  }
}
@keyframes glow-fade-in-b {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
  to {
    opacity: 0.3;
    transform: scale(1);
  }
}

/* Ambient pulse — a slow breathe, kept subtle so it reads as the glow
   "living" rather than blinking. Runs as a THIRD animation chained after
   the entrance: the fade-in owns opacity for its first 0.8s, then this
   takes over from the same value it settled on (0.5 / 0.3), so there is
   no jump at the handoff. Its delay must match the fade-in's duration.
   The floor never approaches 0 — the glow dims and brightens, it never
   disappears. */
@keyframes glow-pulse-a {
  0%,
  100% {
    opacity: 0.5;
  }
  50% {
    opacity: 0.72;
  }
}
@keyframes glow-pulse-b {
  0%,
  100% {
    opacity: 0.3;
  }
  50% {
    opacity: 0.48;
  }
}
.glow-clip-a {
  animation:
    glow-fade-in-a 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
    glow-pulse-a 4.5s ease-in-out 0.8s infinite;
}
.glow-clip-b {
  animation:
    glow-fade-in-b 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both,
    glow-pulse-b 6s ease-in-out 1s infinite;
}

@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* CTA button hover treatment — ported from Nxeon's real .btn-deploy
   pattern (see that codebase's app/globals.css) using Kodely's own brand
   gradient instead of Nxeon's blue/purple one. Two pieces:
   1. .btn-shine — a one-shot shimmer sweep on hover (all CTAs).
   2. .btn-cta-gradient — the background gradient itself shifts position on
      hover (only on buttons whose background already IS the brand
      gradient — a plain dark/monochrome button has no gradient to shift). */
@keyframes btn-shine {
  from {
    left: -40%;
  }
  to {
    left: 120%;
  }
}
.group:hover .btn-shine {
  animation: btn-shine 0.75s ease;
}

.btn-cta-gradient {
  background-image: var(--brand-gradient);
  background-size: 220% 100%;
  background-position: 0% 0;
  transition: background-position 0.6s ease;
}
.group:hover .btn-cta-gradient {
  background-position: 100% 0;
}

/* Prose styling for blog/SEO content (BlogPost.bodyHtml) — hand-rolled
   instead of a Tailwind typography plugin dependency, matching the same
   near-monochrome + generous-whitespace system as the rest of the site. */
.article-body h2 {
  margin-top: 2.75rem;
  margin-bottom: 1rem;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.article-body h3 {
  margin-top: 2rem;
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
  font-weight: 600;
}
.article-body p {
  margin-bottom: 1.25rem;
  line-height: 1.75;
  color: var(--foreground);
}
.article-body ul,
.article-body ol {
  margin: 1.25rem 0 1.25rem 1.25rem;
  line-height: 1.75;
}
.article-body ul {
  list-style: disc;
}
.article-body ol {
  list-style: decimal;
}
.article-body li {
  margin-bottom: 0.4rem;
}
.article-body a {
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--foreground) 30%, transparent);
}
.article-body strong {
  font-weight: 600;
}
.article-body code {
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.875em;
  background: color-mix(in srgb, var(--foreground) 6%, transparent);
  padding: 0.15em 0.4em;
  border-radius: 0.3em;
}
.article-body table {
