(function(){
  const el = document.querySelector('.hero-mock-enter');
  const before = {scrollY: window.scrollY, isHidden: el.classList.contains('is-hidden')};
  window.scrollTo(0, 800);           // scroll the mock into view
  const midRect = el.getBoundingClientRect();
  const vh = window.innerHeight;
  const vis = Math.min(midRect.bottom, vh) - Math.max(midRect.top, 0);
  return JSON.stringify({
    atLoad: before,
    afterScroll: {
      scrollY: window.scrollY,
      visibleFraction: +(vis / midRect.height).toFixed(2),
      isHiddenImmediatelyAfterScroll: el.classList.contains('is-hidden'),
    },
  }, null, 1);
})();

