/* The real thing: a native scroll-driven animation, progressed by the
   element's own position in the viewport. No IntersectionObserver, no
   scroll listener, no React state — every JS-based trigger tried here
   (framer's whileInView, a raw IntersectionObserver, a scroll listener)
   failed to fire in practice, and this removes that entire class of
   failure. `view()` ties progress to the element crossing the viewport;
   the range runs from just after it appears to a third of the way up, so
   it finishes as you arrive at it rather than while it's still an
   off-screen sliver. */
@supports (animation-timeline: view()) {
  .hero-mock-enter {
    animation: hero-mock-in linear both;
    animation-timeline: view();
    animation-range: entry 15% cover 38%;
  }
}

