  // Already on screen at mount (e.g. the browser restored scroll position
  // on reload) — just show it; there is no arrival to animate.
  if (isInView()) return;

  setHidden(true);

  let done = false;
  const reveal = () => {
    if (done) return;
    done = true;
    setHidden(false);
  };
  const onScroll = () => {
    if (isInView()) reveal();
  };

  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onScroll);

  // Belt and braces: an observer in addition to the scroll listener, so
  // whichever signal the browser delivers first wins. They're redundant
  // by design — `reveal()` is idempotent.
  let observer: IntersectionObserver | null = null;
  if (typeof IntersectionObserver !== "undefined") {
    observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) reveal();
      },
      { threshold: 0.3 },
    );
    observer.observe(el);
  }

  // In case layout settled between the check above and listeners binding.
  onScroll();

  return () => {
    done = true;
    window.removeEventListener("scroll", onScroll);
    window.removeEventListener("resize", onScroll);
    observer?.disconnect();
  };
