import { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";

const db = new DatabaseSync("board.sqlite");

const COL = {
  engine: "1d33c435-4cec-4169-af69-b98def3ef513", // AI / Codegen Engine
  features: "d078aec7-31ed-4404-ae5c-50f54d69fa39", // Features & Table-Stakes
  builder: "529349d1-39a0-44ff-a3d2-11a53d29ec65", // Builder / Editor UX
  pricing: "1f540e48-5049-489b-9449-cb5634a5f3b7", // Pricing & Monetization
  risks: "0e7f1fa7-2c70-45b9-92a9-c800699dc612", // Risks & Pitfalls
};

const cards = [
  // ── Learning mode ───────────────────────────────────────────────────────
  {
    col: "engine",
    title: "Learning mode: feed every generation back into the builder",
    priority: "HIGH",
    labels: ["learning", "engine", "quality"],
    desc: `A background loop where the builder gets measurably better at first-go output instead of staying frozen at whatever the prompt says today.

Signals to capture on every build:
- did it compile first try (Build.repairAttempts = 0)
- did the user immediately ask for a fix, and what kind ("too generic", "wrong colors", "add a section")
- did they publish it, or abandon it
- explicit thumbs up/down on the result
- how many edit turns before publish (fewer = better first go)

The output is not "fine-tune a model" — it is a growing set of SKILLS/rules distilled from real failures, injected into the system prompt. Every recurring complaint becomes a rule; every rule gets tested against the golden set before it ships.`,
  },
  {
    col: "engine",
    title: "Capture chat replies as a quality signal",
    priority: "HIGH",
    labels: ["learning", "engine"],
    desc: `What people type after a build is the highest-value feedback we get and we currently throw it away.

Classify each follow-up message into an intent bucket (visual fix / content fix / layout fix / add feature / broken / praise) and count them. The top buckets are a ranked list of exactly what the first generation gets wrong.

Privacy: store the classified BUCKET plus a short redacted excerpt, not the raw prompt body wholesale, and say so in the privacy policy. See [[Trust, Legal & Compliance]].`,
  },
  {
    col: "engine",
    title: "Golden-set eval harness for generation quality",
    priority: "HIGH",
    labels: ["learning", "engine", "quality"],
    desc: `Learning mode is worthless without a scoreboard — otherwise every prompt tweak is a guess and regressions ship silently.

Build a fixed set of ~30 representative prompts (restaurant, SaaS landing, portfolio, barber shop, event, etc). On every prompt/model change, run all 30 and score:
- compiles first try (hard pass/fail)
- Lighthouse-ish checks: has title/meta, responsive, contrast, no placeholder text
- visual diff vs the last accepted run
- a rubric grade from a judge model

Gate: no prompt change ships if green-build-first-try or the rubric average drops. This is the kill-criterion the roadmap already names but nothing measures.`,
  },
  {
    col: "engine",
    title: "Skills library the builder grows into",
    priority: "NORMAL",
    labels: ["learning", "engine"],
    desc: `Distilled learnings live as small, composable skill files (one concern each: hero sections, pricing tables, contact forms, mobile nav, dark mode) rather than one ever-growing mega-prompt.

Benefits: each skill is independently testable against the golden set, cheap to load selectively by site type, and reviewable by a human before it affects real customers. A mega-prompt is the failure mode — it gets long, self-contradictory, and impossible to attribute a regression to.`,
  },

  // ── Asset library ───────────────────────────────────────────────────────
  {
    col: "features",
    title: "Asset library — the builder pulls real media instead of grey boxes",
    priority: "HIGH",
    labels: ["assets", "quality"],
    desc: `Biggest single lever on "does the generated site look real or look like a wireframe". The agent needs a curated, licensed, searchable asset set it can reference by ID with zero network risk at build time.

Categories to cover (parent card — see the child cards for each):
- Photography (by industry, mood, orientation)
- Video loops / backgrounds
- Icons in multiple styles (outline, solid, duotone, 3D, hand-drawn)
- Country flags (all 250, plus regional/state)
- Illustrations & spot art
- Patterns, textures, noise, grain
- Gradients & mesh backgrounds
- Avatars / placeholder people (diverse, consent-clean)
- Blobs, shapes, section dividers & wave separators
- Logos & badges (payment methods, app stores, "as seen in", integration marks)
- Device mockups / screenshot frames
- Lottie / animated micro-illustrations
- Maps & location graphics
- Emoji sets
- Font pairings and colour palettes as first-class assets
- UI sound effects (low priority)

Hard requirement: every asset carries licence + attribution metadata. Shipping a customer a site with an unlicensed stock photo is a legal problem they inherit from us.`,
  },
  {
    col: "features",
    title: "Asset search the agent can actually query",
    priority: "HIGH",
    labels: ["assets", "engine"],
    desc: `Semantic search over the asset library, exposed to the builder as a tool ("find_asset: hero photo, italian restaurant, warm, landscape"). Returns stable IDs the generated code references.

Why a tool and not a dump in the prompt: the library will be tens of thousands of items — it cannot live in context, and hardcoding a handful of URLs into the prompt is how every site ends up using the same six photos.`,
  },
  {
    col: "features",
    title: "Asset delivery: optimisation + CDN",
    priority: "NORMAL",
    labels: ["assets", "performance"],
    desc: `Serve every asset as WebP/AVIF with responsive sizes and lazy loading, from our own CDN path. Generated sites are judged on load speed; a 4MB hero JPEG undoes the whole build.

Also gives us: no hotlinking to third parties, no broken images when an external host rotates URLs, and a CSP that stays strict.`,
  },
  {
    col: "features",
    title: "Brand kit — user uploads their own assets",
    priority: "NORMAL",
    labels: ["assets", "builder"],
    desc: `Logo, colours, fonts, product photos, team headshots. Uploaded once per project (or per account) and automatically preferred by the builder over stock.

This is the difference between "a nice generic template" and "my business's website" — and it is the moment a hobby user becomes a paying one.`,
  },
  {
    col: "features",
    title: "AI image generation as the fallback when the library misses",
    priority: "LOW",
    labels: ["assets", "cost"],
    desc: `When nothing in the library fits, generate. Deliberately the fallback and not the default: generated images cost real money per call, are slow, and are still unreliable for text-in-image and product accuracy.

Needs its own credit line-item so it never silently inflates a build's cost — see the anti-bill-shock contract in lib/credits.ts.`,
  },

  // ── Build-time experience ───────────────────────────────────────────────
  {
    col: "builder",
    title: "Logo-animation pre-loader while the site builds",
    priority: "NORMAL",
    labels: ["builder", "brand", "ux"],
    desc: `A branded animated Kodely mark on the build screen. A 60-90s wait with a static spinner feels broken; the same wait with a considered loop feels like craft — and it is the single most-watched screen in the product.`,
  },
  {
    col: "builder",
    title: "Build animation — show the site assembling",
    priority: "NORMAL",
    labels: ["builder", "ux"],
    desc: `Motion in the preview pane as the build progresses: skeleton blocks resolving into sections, files appearing in the tree, a subtle shimmer as each part lands.

Perceived speed matters more than actual speed here. Competitors that show nothing during generation get abandoned mid-build.`,
  },
  {
    col: "builder",
    title: "Live progress narration in the chat while building",
    priority: "HIGH",
    labels: ["builder", "ux"],
    desc: `Stream real, specific status lines into the chat as the agent works — "Planning the layout…", "Writing the hero section", "Adding the menu page", "Compiling", "Deploying preview" — with a typing/pulse animation.

Must be driven by ACTUAL agent events (tool calls, files written), not a fake timed script. Fake progress that finishes before the real build does is worse than no progress at all, and users spot it immediately.

The SDK already streams tool-use events; this is plumbing them to the client, not inventing them.`,
  },
  {
    col: "builder",
    title: "Wake agent — resume a stalled or paused build",
    priority: "NORMAL",
    labels: ["builder", "reliability"],
    desc: `A control to nudge the agent back to work when a build stalls, times out, or is waiting on something, instead of the user's only option being "start over and pay again".

NEEDS A DECISION when picked up — two readings of this idea:
(a) reliability: detect a hung build and let the user resume it from the last good state at no extra credit cost;
(b) ambient: an idle agent that wakes on a schedule or a trigger to continue long-running work.

(a) is the one that removes a real user-facing failure; (b) is a bigger feature. Recommend building (a) first.`,
  },

  // ── Free credits / social ───────────────────────────────────────────────
  {
    col: "pricing",
    title: "Free credit gifts for following our socials",
    priority: "NORMAL",
    labels: ["growth", "credits"],
    desc: `50 credits each for: joining our Discord, following on Instagram, liking the Facebook page, following on LinkedIn. 200 credits total available.

Sizing check against lib/credits.ts: signup grant is 750 credits and a real build runs ~144. So the full social set is worth roughly 1.4 extra builds — meaningful to the user, cheap to us, and it buys real distribution on four platforms.

Presented as a small checklist in the credits UI, not a nag.`,
  },
  {
    col: "pricing",
    title: "Verified social connections that actually trigger the grant",
    priority: "NORMAL",
    labels: ["growth", "credits", "integrations"],
    desc: `The grant has to be earned, not claimed. Per platform:
- Discord: OAuth + guild-membership check via the bot. Cleanest of the four.
- Instagram / Facebook: Meta Graph API. Follower checks are heavily restricted — likely needs a workaround (e.g. verified account link + manual/heuristic check).
- LinkedIn: no follower-check API. Same problem.

Realistic plan: Discord is genuinely verifiable; the other three need either a lighter mechanism (click through + connect account + delayed grant) or acceptance that some abuse gets through. Decide the tolerance before building — do NOT ship an honour-system button that grants credits on click.`,
  },
  {
    col: "risks",
    title: "Anti-abuse for credit gifts",
    priority: "HIGH",
    labels: ["growth", "credits", "abuse"],
    desc: `Free credits + weak verification = farming. Every granted credit is real model spend on our card.

Minimum guards: one grant per platform per account, ever (ledger reason string is the idempotency key); one grant per external social identity across all accounts (so one Instagram can't feed 50 signups); no grants for accounts under an age/verification threshold; alerting on grant velocity.

The ledger design already makes this auditable — grants are rows, not a mutable counter.`,
  },
  {
    col: "builder",
    title: "Low-credit warning at the credit bar",
    priority: "HIGH",
    labels: ["credits", "ux", "trust"],
    desc: `Warn near the credit meter before the user hits zero — not at zero, and never mid-build with a dead end.

Behaviour: a quiet amber state at ~20% remaining with the estimated builds left ("about 1 more build"), and a pre-flight note when a build's estimate exceeds the balance. Top-up is one click from the warning.

This is the same trust wedge as the no-charge-on-failure rule: the category's deepest wound is bill shock and dead ends, and the fix is telling people what is about to happen BEFORE it happens.`,
  },
];

const insert = db.prepare(
  `INSERT INTO cards (id, columnId, title, description, type, priority, labels, position)
   VALUES (?, ?, ?, ?, 'FEATURE', ?, ?, ?)`,
);
const maxPos = db.prepare(
  "SELECT COALESCE(MAX(position), -1) AS p FROM cards WHERE columnId = ?",
);

const nextPos = new Map();
for (const c of cards) {
  const colId = COL[c.col];
  if (!nextPos.has(colId)) nextPos.set(colId, maxPos.get(colId).p + 1);
  const pos = nextPos.get(colId);
  nextPos.set(colId, pos + 1);
  insert.run(randomUUID(), colId, c.title, c.desc, c.priority, JSON.stringify(c.labels), pos);
  console.log(`+ [${c.col}] ${c.title}`);
}

console.log(`\n${cards.length} cards added.`);

