  @{n='/ on kodely.me';h='kodely.me';p='/'}
)
foreach ($t in $tests) {
  try {
    $r = Invoke-WebRequest -Uri "http://localhost:3009$($t.p)" -Headers @{Host=$t.h} -MaximumRedirection 0 -SkipHttpErrorCheck -ErrorAction Stop
    "$($t.n) -> $($r.StatusCode) $(if($r.Headers.Location){'-> '+$r.Headers.Location})"
  } catch { "$($t.n) -> ERROR $($_.Exception.Message)" }
}

$tests = @(
  @{n='/admin on WRONG host      ';h='kodely.me';p='/admin'},
