import { mkdtemp, rm, readFile, readdir } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { materializeAssets, formatMatchesForTool } from "./lib/assets/materialize.ts";
import { findAssets } from "./lib/assets/index.ts";
import { adaptPromptForSdk } from "./lib/agent-sdk.ts";

// 1. Does the catalogue materialize, and is it dot-prefixed (so readFileTree skips it)?
const dir = await mkdtemp(path.join(tmpdir(), "kodely-assettest-"));
const n = await materializeAssets(dir);
const top = await readdir(dir);
const index = await readFile(path.join(dir, ".kodely-assets", "INDEX.md"), "utf8");

console.log(`materialized: ${n} assets`);
console.log(`top-level entries: ${JSON.stringify(top)}`);
console.log(`all dot-prefixed (readFileTree skips): ${top.every((e) => e.startsWith("."))}`);
console.log(`INDEX.md bytes: ${index.length}`);

// 2. Does a line in the index point at a file that actually exists and has content?
const line = index.split("\n").find((l) => l.startsWith("- `icon:"));
console.log(`sample index line: ${line?.slice(0, 110)}`);
const rel = line?.match(/→ `([^`]+)`/)?.[1];
if (!rel) throw new Error("index line has no file reference");
const body = await readFile(path.join(dir, rel), "utf8");
console.log(`referenced file resolves: ${rel} (${body.length} bytes)`);
console.log(`  starts: ${body.split("\n")[0]}`);

// 3. Does grep-style search find trade vocabulary?
for (const q of ["plumber wrench", "warm sunset gradient", "wave divider", "french flag", "coffee"]) {
  const m = findAssets(q, { limit: 3 });
  console.log(`find "${q}" -> ${m.map((x) => x.id).join(", ") || "(none)"}`);
}

// 4. Does the API tool formatter produce something pasteable?
const formatted = formatMatchesForTool(findAssets("phone icon", { limit: 1 }));
console.log(`\ntool result sample:\n${formatted.slice(0, 240)}`);

// 5. Does the SDK prompt swap fire, and does it throw if the sentence drifts?
const { SYSTEM_FOR_TEST } = await import("./lib/agent.ts").then((m) => ({
  SYSTEM_FOR_TEST: (m as unknown as { __SYSTEM?: string }).__SYSTEM,
})).catch(() => ({ SYSTEM_FOR_TEST: undefined }));
void SYSTEM_FOR_TEST;

try {
  adaptPromptForSdk("nothing relevant here");
  console.log("\nadaptPromptForSdk: FAIL — should have thrown on a prompt missing the contracts");
} catch (e) {
  console.log(`\nadaptPromptForSdk throws when contracts missing: ok (${(e as Error).message.slice(0, 60)}…)`);
}

await rm(dir, { recursive: true, force: true });

