const FOUNDATION = `<!doctype html><html lang="en"><head>
    <meta charset="UTF-8" />
    <title>Kodely Site</title>
    <meta name="description" content="" />
    <meta property="og:title" content="" />
  </head><body><div id="root"></div></body></html>`;
const NO_HEAD = `<div>fragment only</div>`;
const SINGLE_Q = `<html><head><meta name='description' content='old'><title>Old</title></head><body></body></html>`;

const out = applyHead(FOUNDATION, v);
const checks = {
  "title replaced":                 /<title>Bloom &amp; Co<\/title>/.test(out),
  "placeholder title gone":         !out.includes("Kodely Site"),
  "empty description filled":       /name="description" content="The &quot;best&quot; studio"/.test(out),
  "empty og:title filled":          /property="og:title" content="Bloom &amp; Co"/.test(out),
  "missing og:description injected":/property="og:description" content="Reformer classes"/.test(out),
  "ampersand escaped once":         !out.includes("&amp;amp;"),
  "no head -> unchanged":           applyHead(NO_HEAD, v) === NO_HEAD,
  "single quotes handled":          /content="The &quot;best&quot; studio"/.test(applyHead(SINGLE_Q, v)),
  "idempotent":                     applyHead(out, v) === out,
  "body untouched":                 out.includes('<div id="root"></div>'),
};
let bad = 0;
for (const [k, ok] of Object.entries(checks)) { if (!ok) bad++; console.log(`${ok ? "ok  " : "FAIL"}  ${k}`); }
console.log(`\n${Object.keys(checks).length - bad}/${Object.keys(checks).length} passed`);
EOF
