import { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";

const db = new DatabaseSync("board.sqlite");
const B = "720aa8c1-d259-4e49-b777-c58965efabd1";

// A distinct stage, because "the work is finished" and "customers can use it"
// are different facts and collapsing them is how a board starts lying. Nothing
// from this session is deployed — the schema has to reach staging and prod
// before any of it ships — so Shipped stays empty of this work until it does.
const DONE_NAME = "Done — awaiting deploy";

const colId = (name) =>
  db.prepare("SELECT id FROM columns WHERE boardId = ? AND name = ?").get(B, name)?.id;

let done = colId(DONE_NAME);
if (!done) {
  // Sits between In Progress and Shipped, so the board reads left-to-right as
  // the work actually flows.
  const after = db.prepare("SELECT position FROM columns WHERE boardId = ? AND name = ?").get(B, "Blocked");
  const at = after.position + 1;
  db.prepare("UPDATE columns SET position = position + 1 WHERE boardId = ? AND position >= ?").run(B, at);
  done = randomUUID();
  db.prepare("INSERT INTO columns (id, boardId, name, position) VALUES (?, ?, ?, ?)").run(done, B, DONE_NAME, at);
  console.log(`created column "${DONE_NAME}" at position ${at}`);
}

// Cards whose work is genuinely complete and verified. Anything still being
// worked, or only partly delivered, deliberately stays in In Progress.
const COMPLETE = [
  "Golden-set eval harness for generation quality",
  "Asset library — the builder pulls real media instead of grey boxes",
  "Asset search the agent can actually query",
  "Logo-animation pre-loader while the site builds",
  "Build animation — show the site assembling",
  "Live progress narration in the chat while building",
  "Low-credit warning at the credit bar",
  "Activation funnel dashboard (signup → prompt → build → deploy → paid)",
  "Project dashboard: list, rename, duplicate, deploy status",
  "Auto-enhance: expand a rough prompt into a full spec",
  "Content policy + AUP moderation",
  "Templates & one-click quick-starts",
  "Billing UX: plans, live usage meter, buy credits, invoices",
